mapper.select:
SELECT * FROM ( SELECT a.*, rownum rnum FROM ( SELECT f.fare_id, f.price, f.is_active, dep.iata_code AS departure_airport_code, arr.iata_code AS arrival_airport_code, sc.class_name, s.season_name FROM FARE f JOIN ROUTE r ON f.route_id = r.route_id JOIN AIRPORT dep ON r.departure_airport_id = dep.airport_id JOIN AIRPORT arr ON r.arrival_airport_id = arr.airport_id JOIN SEAT_CLASS sc ON f.seat_class_id = sc.seat_class_id JOIN SEASON s ON f.season_id = s.season_id
sc.class_name LIKE '%' || #{keyword} || '%'
s.season_name LIKE '%' || #{keyword} || '%'
AND f.is_active = #{is_active}
ORDER BY f.fare_id DESC ) a )
WHERE rnum >= #{start} AND rnum <= #{end}

mapper.update:
UPDATE FARE 
SET price = #{price}
WHERE fare_id = #{fare_id}

UPDATE FARE 
SET is_active = #{is_active}
WHERE fare_id = #{fare_id}

UPDATE FARE 
SET is_active = 'N'
WHERE fare_id = #{fare_id}
